import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D4.3 · 安全配对、推送与设备撤销","description":"Hearth D4.3 开发增量：手机和桌面通过短期码或二维码配对；手机丢失时可以立即撤销，撤销后无法继续审批或接管。","frontmatter":{"title":"D4.3 · 安全配对、推送与设备撤销","description":"Hearth D4.3 开发增量：手机和桌面通过短期码或二维码配对；手机丢失时可以立即撤销，撤销后无法继续审批或接管。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/d4-3.md","filePath":"delivery/stage-4/d4-3.md","lastUpdated":1793761874000}'),r={name:"delivery/stage-4/d4-3.md"};function d(h,a,s,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 4 · D4.3 · 3 / 5</p><h1 id="d4-3-·-安全配对、推送与设备撤销" tabindex="-1">D4.3 · 安全配对、推送与设备撤销 <a class="header-anchor" href="#d4-3-·-安全配对、推送与设备撤销" aria-label="Permalink to &quot;D4.3 · 安全配对、推送与设备撤销&quot;">​</a></h1><p class="lead">手机和桌面必须通过短期配对建立信任，丢失设备时能立即撤销审批、接管和读取权限。</p><p class="page-meta">STAGE 4 · D4.3 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>手机和桌面通过短期码或二维码配对；手机丢失时可以立即撤销，撤销后无法继续审批或接管。</div><div><strong>完成门槛</strong>审批不可重放；丢失设备可撤销；撤销后任务与产物访问立即受限；推送不含敏感内容；配对不能绕过用户确认。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>手机和桌面通过短期码或二维码配对；手机丢失时可以立即撤销，撤销后无法继续审批或接管。</p><p>Stage 4 的价值不是后台运行，而是在正确的时间以可接受的打扰做正确的事。主动性必须建立在既有恢复与审批之上。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1–3 的恢复、审批、验证、接管和撤销已经稳定。</li><li>已明确允许触发主动任务的来源、时间窗口、预算和静默时段。</li><li>手机只作为查看、审批、接管和发起入口，不成为默认执行权威。</li><li>D4.2 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-公钥配对与用户确认" tabindex="-1">01 · 公钥配对与用户确认 <a class="header-anchor" href="#_01-·-公钥配对与用户确认" aria-label="Permalink to &quot;01 · 公钥配对与用户确认&quot;">​</a></h3><p>手机生成密钥对，通过一次性二维码或短码与主设备绑定；用户必须在主设备确认配对、设备名称和权限范围。配对记录包含公钥、创建时间、最后使用和信任来源，短期会话到期后重新确认。</p><h3 id="_02-·-加密中继与最小元数据" tabindex="-1">02 · 加密中继与最小元数据 <a class="header-anchor" href="#_02-·-加密中继与最小元数据" aria-label="Permalink to &quot;02 · 加密中继与最小元数据&quot;">​</a></h3><p>推送中继只看到路由所需的设备标识、消息类型和密文，不能读取任务正文、审批参数或产物。消息使用端到端加密和防重放 nonce；中继不可用时降级为主动查询，不把敏感内容退回普通短信或邮件。</p><h3 id="_03-·-审批-nonce、参数绑定与过期" tabindex="-1">03 · 审批 nonce、参数绑定与过期 <a class="header-anchor" href="#_03-·-审批-nonce、参数绑定与过期" aria-label="Permalink to &quot;03 · 审批 nonce、参数绑定与过期&quot;">​</a></h3><p>审批请求绑定 approvalId、任务、参数哈希、nonce、设备、过期时间和一次性签名。参数修改、设备变化或过期都会使审批失效；重复 nonce 被拒绝，旧审批不能用于新动作，拒绝记录同步回主设备。</p><h3 id="_04-·-设备撤销与丢失演练" tabindex="-1">04 · 设备撤销与丢失演练 <a class="header-anchor" href="#_04-·-设备撤销与丢失演练" aria-label="Permalink to &quot;04 · 设备撤销与丢失演练&quot;">​</a></h3><p>设备页支持远程撤销、清除会话和查看最近访问。撤销后旧设备不能审批、接管或读取新事件；丢失演练覆盖撤销延迟、离线设备重新上线、密钥轮换和重新配对，所有安全事件都有可读审计。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd/triggers</code> — Trigger 适配器、去重键、候选生成与降级</li><li><code>packages/control</code> — 自主级别、候选策略、风险门槛与 kill switch</li><li><code>packages/attention</code> — 注意力预算、静默时段、通知聚合与价值评分</li><li><code>apps/pwa</code> — 移动任务卡、审批、接管、离线只读与推送入口</li><li><code>packages/devices/pairing</code> — 公钥配对、短期会话与远程撤销</li><li><code>packages/relay</code> — 端到端加密推送、最小元数据与重放防护</li><li><code>apps/web</code> — 为什么现在、主动收件箱、强度设置与中断历史</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>TriggerEvent</code></td><td>triggerId、source、dedupeKey、observedAt、payloadRef、scope、sensitivity；重复事件不能生成重复任务。</td></tr><tr><td><code>ProactiveCandidate</code></td><td>candidateId、whyNow、proposedAction、autonomyLevel、risk、budget、expiresAt；候选不是授权。</td></tr><tr><td><code>AttentionBudget</code></td><td>window、maxInterruptions、quietHours、valueThreshold、spent；预算耗尽必须停止主动打扰。</td></tr><tr><td><code>MobileApproval</code></td><td>approvalId、nonce、parameterHash、expiresAt、deviceId、signature；离线状态不得确认外部副作用。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:triggers：重复事件、乱序、失效来源和预算耗尽</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:attention：静默时段、聚合、疲劳阈值和</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:pwa：离线、断网、生物识别、重放和远程撤销</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:proactive：主动与手动对照的成功率、打断和满意度</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-4/d4-3.html">D4.3 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：公钥配对与用户确认、加密中继与最小元数据、审批 nonce、参数绑定与过期、设备撤销与丢失演练。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“重复触发导致通知轰炸”。页面必须显示“聚合为一个候选卡并标注重复来源。”，然后按“提高去重窗口、暂停触发或降低主动级别。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：审批不可重放；丢失设备可撤销；撤销后任务与产物访问立即受限；推送不含敏感内容；配对不能绕过用户确认。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>配对与二维码流程</li><li>nonce/参数绑定测试</li><li>撤销与会话失效演示</li><li>安全审计记录</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 审批不可重放；丢失设备可撤销；撤销后任务与产物访问立即受限；推送不含敏感内容；配对不能绕过用户确认。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>重复触发导致通知轰炸</td><td>聚合为一个候选卡并标注重复来源。</td><td>提高去重窗口、暂停触发或降低主动级别。</td></tr><tr><td>手机审批被重放</td><td>审批拒绝并显示设备/时间不匹配。</td><td>要求重新认证并重新生成审批请求。</td></tr><tr><td>后台预算耗尽</td><td>主动任务停在预算边界，显示已停止原因。</td><td>等待用户提高预算或手动继续，不自动透支。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不在没有恢复、审批和验证的前提下开放主动循环。</li><li>不为了活跃度制造任务或通知。</li><li>不把手机变成长期持有主凭据的执行设备。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/control-plane.html">控制面与自主性</a></li><li><a href="/hearth-os/architecture/gateway.html">个人网关</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li><li><a href="/hearth-os/architecture/frontend-experience.html">前端与移动体验</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-4/d4-4.html">D4.4 · 注意力预算与主动试跑</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const k=e(r,[["render",d]]);export{u as __pageData,k as default};
